/// Light status at start of the walk

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum WalkLightStatus<S: BosStr = DefaultStr> {
    Bright,
    Steady,
    Dim,
    Flickering,
    Dying,
    FullCharge,
    Charged,
    Low,
    Critical,
    Dead,
    Other(S),
}

impl<S: BosStr> WalkLightStatus<S> {
    pub fn as_str(&self) -> &str {
        match self {
            Self::Bright => "bright",
            Self::Steady => "steady",
            Self::Dim => "dim",
            Self::Flickering => "flickering",
            Self::Dying => "dying",
            Self::FullCharge => "fullCharge",
            Self::Charged => "charged",
            Self::Low => "low",
            Self::Critical => "critical",
            Self::Dead => "dead",
            Self::Other(s) => s.as_ref(),
        }
    }
    /// Construct from a string-like value, matching known values.
    pub fn from_value(s: S) -> Self {
        match s.as_ref() {
            "bright" => Self::Bright,
            "steady" => Self::Steady,
            "dim" => Self::Dim,
            "flickering" => Self::Flickering,
            "dying" => Self::Dying,
            "fullCharge" => Self::FullCharge,
            "charged" => Self::Charged,
            "low" => Self::Low,
            "critical" => Self::Critical,
            "dead" => Self::Dead,
            _ => Self::Other(s),
        }
    }
}

